CREATE OR ALTER PROCEDURE [dbo].[uspTemperatureLog_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @StorageZoneId UNIQUEIDENTIFIER = NULL
	, @StorageLocationId UNIQUEIDENTIFIER = NULL
	, @MaterialLotId UNIQUEIDENTIFIER = NULL
	, @ProductionBatchId UNIQUEIDENTIFIER = NULL
	, @MeasurementType NVARCHAR(MAX) = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[StorageZoneId]
			, t.[StorageLocationId]
			, t.[MaterialLotId]
			, t.[ProductionBatchId]
			, t.[MeasurementType]
			, t.[TemperatureC]
			, t.[MinAllowedC]
			, t.[MaxAllowedC]
			, t.[IsWithinRange]
			, t.[MeasuredAt]
			, t.[DeviceCode]
			, t.[SourceChannel]
			, t.[RecordedBy]
			, t.[CorrectiveAction]
			, t.[EvidenceUrl]
			, t.[CreatedDate]
		FROM [dbo].[TemperatureLog] AS t
		
		WHERE (ISNULL(@SearchText, '') = '' OR t.[DeviceCode] LIKE CONCAT('%', @SearchText, '%'))
			AND (@StorageZoneId IS NULL OR t.[StorageZoneId] = @StorageZoneId)
			AND (@StorageLocationId IS NULL OR t.[StorageLocationId] = @StorageLocationId)
			AND (@MaterialLotId IS NULL OR t.[MaterialLotId] = @MaterialLotId)
			AND (@ProductionBatchId IS NULL OR t.[ProductionBatchId] = @ProductionBatchId)
			AND (ISNULL(@MeasurementType, '') = '' OR t.[MeasurementType] = @MeasurementType)
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'storageZoneId' THEN r.[StorageZoneId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'storageZoneId' THEN r.[StorageZoneId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'storageLocationId' THEN r.[StorageLocationId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'storageLocationId' THEN r.[StorageLocationId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'materialLotId' THEN r.[MaterialLotId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'materialLotId' THEN r.[MaterialLotId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'productionBatchId' THEN r.[ProductionBatchId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'productionBatchId' THEN r.[ProductionBatchId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'measurementType' THEN r.[MeasurementType] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'measurementType' THEN r.[MeasurementType] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'temperatureC' THEN r.[TemperatureC] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'temperatureC' THEN r.[TemperatureC] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'minAllowedC' THEN r.[MinAllowedC] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'minAllowedC' THEN r.[MinAllowedC] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'maxAllowedC' THEN r.[MaxAllowedC] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'maxAllowedC' THEN r.[MaxAllowedC] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'isWithinRange' THEN r.[IsWithinRange] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'isWithinRange' THEN r.[IsWithinRange] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'measuredAt' THEN r.[MeasuredAt] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'measuredAt' THEN r.[MeasuredAt] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'deviceCode' THEN r.[DeviceCode] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'deviceCode' THEN r.[DeviceCode] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'sourceChannel' THEN r.[SourceChannel] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'sourceChannel' THEN r.[SourceChannel] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'recordedBy' THEN r.[RecordedBy] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'recordedBy' THEN r.[RecordedBy] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'correctiveAction' THEN r.[CorrectiveAction] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'correctiveAction' THEN r.[CorrectiveAction] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'evidenceUrl' THEN r.[EvidenceUrl] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'evidenceUrl' THEN r.[EvidenceUrl] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
